x_snowwall:{n:"雪墙",cost:2,type:"skl",r:"R",fam:"none",img:"egsk",d:u=>`获得 ${U(u,14,18)} 护盾。下雪时再获得 8`,fx:(B,u)=>{B.block(U(u,14,18)+(B.wx==="snow"?8:0))}},
