bs_bloodbeast:[["xch","冰原血兽","热的。"],["n1","功夫奶蛙","它在说什么？"],["xch","冰原血兽","好久没闻到热的东西了。"]],
bw_bloodbeast:[["xch","冰原血兽","冷。"],["xch","冰原血兽","以前我也是热的。"]],
